from typing import Optional

import requests
from bs4 import BeautifulSoup
from tax_authority_api.const import MAIN_URL, YEAR_PAGE, TAX_CODES_FOR_SPOUSE, FamilyStatus
from tax_authority_api.schemes import TaxResult, PersonalDetails, Report106Codes, SpouseReport106Codes
from tax_authority_api.utils import parse_tax_results


class TaxSimulator:
    def __init__(self, year_suffix):
        self.main_url = MAIN_URL
        self.year_page = YEAR_PAGE.format(year_suffix=year_suffix)
        self.year_suffix = year_suffix
        self.session = requests.Session()
        self.session.headers.update({
            'User-Agent': 'Mozilla/5.0',
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
            'Referer': self.main_url,
        })

    def prepare_form(self, personal_details: PersonalDetails, report_106_codes: Report106Codes):
        # Initialize session and get form
        self.session.get(self.main_url)
        res = self.session.get(self.year_page)
        soup = BeautifulSoup(res.text, 'html.parser')
        form_data = {
            tag['name']: tag.get('value', '')
            for tag in soup.select('input[name]')
        }
        # Fill in personal details
        form_data.update({
            'ctl00$ctl00$ContentUsersPage$ChildContent1$ledambzr': personal_details.dob['month'],
            'ctl00$ctl00$ContentUsersPage$ChildContent1$ledabzr': personal_details.dob['year'],
            'ctl00$ctl00$ContentUsersPage$ChildContent1$mish': personal_details.family_status,
            'ctl00$ctl00$ContentUsersPage$ChildContent1$sex': personal_details.gender,
            'ctl00$ctl00$ContentUsersPage$ChildContent1$okHidden': 'ok',
            'ctl00$ctl00$ContentUsersPage$ChildContent1$chk020': 'on',
            f'ctl00$ctl00$ContentUsersPage$ChildContent1$CNTCurrYear': f"20{self.year_suffix}",
            f'ctl00$ctl00$ContentUsersPage$ChildContent1$CookieNameFake': f"{self.year_suffix}_Fake",
            f'ctl00$ctl00$ContentUsersPage$ChildContent1$CookieName': f"{self.year_suffix}_doch",
        })
        # Handle spouse details if applicable
        if personal_details.family_status == FamilyStatus.MARRIED and personal_details.spouse:
            form_data.update({
                'ctl00$ctl00$ContentUsersPage$ChildContent1$chk021': 'on',
                'ctl00$ctl00$ContentUsersPage$ChildContent1$ledambz': personal_details.spouse['dob']['month'],
                'ctl00$ctl00$ContentUsersPage$ChildContent1$ledabz': personal_details.spouse['dob']['year'],
                'ctl00$ctl00$ContentUsersPage$ChildContent1$sexbz': f"{personal_details.spouse['gender']}bz"
            })
        # Add salary data
        for code, value in report_106_codes.codes.items():
            field_name = f'ctl00$ctl00$ContentUsersPage$ChildContent1$txt{code}'
            form_data[field_name] = value
        return form_data

    def submit(self, form_data: dict) -> str:
        response = self.session.post(self.year_page, data=form_data)
        if response.status_code != 200:
            raise Exception(f"Failed to submit form: {response.status_code}")
        return response.text

    def calculate_refund(self,
                         personal_details: PersonalDetails,
                         report_106_codes: Report106Codes,
                         spouse_report_106_codes: Optional[SpouseReport106Codes]) -> TaxResult | None:
        if personal_details.family_status == FamilyStatus.SINGLE:
            report_106_codes.codes = {code: value for code, value in report_106_codes.codes.items() if
                                   code not in TAX_CODES_FOR_SPOUSE}
        elif personal_details.family_status == FamilyStatus.MARRIED:
            spouse_report_106_codes.codes = {code: value for code, value in spouse_report_106_codes.codes.items() if
                                   code in TAX_CODES_FOR_SPOUSE}
            # merging spouse codes if applicable
            if personal_details.family_status == FamilyStatus.MARRIED:
                report_106_codes.codes.update(spouse_report_106_codes.codes)

        data = self.prepare_form(personal_details, report_106_codes)
        response = self.submit(data)
        return parse_tax_results(response)

from typing import Optional
import requests from bs4 import BeautifulSoup from loguru import logger
from tax_authority_api.const import MAIN_URL, YEAR_PAGE, TAX_CODES_FOR_SPOUSE, FamilyStatus from tax_authority_api.schemes import TaxResult, PersonalDetails, Report106Codes, SpouseReport106Codes from tax_authority_api.utils import parse_tax_results
class TaxSimulator: def __init__(self, year_suffix): self.main_url = MAIN_URL self.year_page = YEAR_PAGE.format(year_suffix=year_suffix) self.year_suffix = year_suffix self.session = requests.Session() self.session.headers.update({ 'User-Agent': 'Mozilla/5.0', 'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8', 'Referer': self.main_url, }) logger.info(f"TaxSimulator initialized for year 20{year_suffix}")
def prepare_form(self, personal_details: PersonalDetails, report_106_codes: Report106Codes): logger.debug(f"Preparing form for tax calculation - Family status: {personal_details.family_status}")
# Initialize session and get form logger.debug("Fetching main page and year-specific page") self.session.get(self.main_url) res = self.session.get(self.year_page)
if res.status_code != 200: logger.error(f"Failed to fetch year page: {res.status_code}") raise Exception(f"Failed to fetch year page: {res.status_code}")
logger.debug("Parsing form data from tax authority website") soup = BeautifulSoup(res.text, 'html.parser') form_data = { tag['name']: tag.get('value', '') for tag in soup.select('input[name]') }
# Fill in personal details form_data.update({ 'ctl00$ctl00$ContentUsersPage$ChildContent1$ledambzr': personal_details.dob['month'], 'ctl00$ctl00$ContentUsersPage$ChildContent1$ledabzr': personal_details.dob['year'], 'ctl00$ctl00$ContentUsersPage$ChildContent1$mish': personal_details.family_status, 'ctl00$ctl00$ContentUsersPage$ChildContent1$sex': personal_details.gender, 'ctl00$ctl00$ContentUsersPage$ChildContent1$okHidden': 'ok', 'ctl00$ctl00$ContentUsersPage$ChildContent1$chk020': 'on', f'ctl00$ctl00$ContentUsersPage$ChildContent1$CNTCurrYear': f"20{self.year_suffix}", f'ctl00$ctl00$ContentUsersPage$ChildContent1$CookieNameFake': f"{self.year_suffix}_Fake", f'ctl00$ctl00$ContentUsersPage$ChildContent1$CookieName': f"{self.year_suffix}_doch", }) logger.debug(f"Added personal details to form - DOB: {personal_details.dob['month']}/{personal_details.dob['year']}")
# Handle spouse details if applicable if personal_details.family_status == FamilyStatus.MARRIED and personal_details.spouse: logger.debug("Adding spouse details for married couple") form_data.update({ 'ctl00$ctl00$ContentUsersPage$ChildContent1$chk021': 'on', 'ctl00$ctl00$ContentUsersPage$ChildContent1$ledambz': personal_details.spouse['dob']['month'], 'ctl00$ctl00$ContentUsersPage$ChildContent1$ledabz': personal_details.spouse['dob']['year'], 'ctl00$ctl00$ContentUsersPage$ChildContent1$sexbz': f"{personal_details.spouse['gender']}bz" })
# Add salary data logger.debug(f"Adding {len(report_106_codes.codes)} tax codes to form") for code, value in report_106_codes.codes.items(): field_name = f'ctl00$ctl00$ContentUsersPage$ChildContent1$txt{code}' form_data[field_name] = value logger.debug(f"Added tax code {code}: {value}")
logger.info("Form preparation completed successfully") return form_data
def submit(self, form_data: dict) -> str: logger.info(f"Submitting form to tax authority website: {self.year_page}") response = self.session.post(self.year_page, data=form_data)
if response.status_code != 200: logger.error(f"Failed to submit form: HTTP {response.status_code}") raise Exception(f"Failed to submit form: {response.status_code}")
logger.success("Form submitted successfully to tax authority") logger.debug(f"Response length: {len(response.text)} characters") return response.text
def calculate_refund(self, personal_details: PersonalDetails, report_106_codes: Report106Codes, spouse_report_106_codes: Optional[SpouseReport106Codes]) -> TaxResult | None:
logger.info(f"Starting tax refund calculation for {personal_details.family_status} person")
if personal_details.family_status == FamilyStatus.SINGLE: logger.debug("Processing single person - filtering out spouse-specific tax codes") original_count = len(report_106_codes.codes) report_106_codes.codes = {code: value for code, value in report_106_codes.codes.items() if code not in TAX_CODES_FOR_SPOUSE} filtered_count = len(report_106_codes.codes) logger.debug(f"Filtered tax codes: {original_count} -> {filtered_count} (removed {original_count - filtered_count} spouse codes)")
elif personal_details.family_status == FamilyStatus.MARRIED: if not spouse_report_106_codes: logger.error("Married status requires spouse report codes but none provided") raise ValueError("Spouse report codes required for married status")
logger.debug("Processing married couple - merging spouse tax codes") spouse_original_count = len(spouse_report_106_codes.codes) spouse_report_106_codes.codes = {code: value for code, value in spouse_report_106_codes.codes.items() if code in TAX_CODES_FOR_SPOUSE} spouse_filtered_count = len(spouse_report_106_codes.codes) logger.debug(f"Spouse tax codes: {spouse_original_count} -> {spouse_filtered_count}")
# merging spouse codes if applicable main_codes_count = len(report_106_codes.codes) report_106_codes.codes.update(spouse_report_106_codes.codes) final_count = len(report_106_codes.codes) logger.debug(f"Merged codes: {main_codes_count} + {spouse_filtered_count} = {final_count}")
try: data = self.prepare_form(personal_details, report_106_codes) response = self.submit(data) result = parse_tax_results(response)
if result: logger.success("Tax refund calculation completed successfully") else: logger.warning("Tax calculation returned no results")
return result
except Exception as e: logger.error(f"Tax calculation failed: {e}") logger.exception("Full exception details:") raise

import re

from tax_authority_api.const import TAX_CODES
from tax_authority_api.schemes import Report106Codes


def preprocess_image(pil_image):
    # to grayscale
    gray = pil_image.convert("L")
    # apply fixed threshold -> binary (0 or 255) but keep mode "L"
    bw = gray.point(lambda p: 255 if p > 180 else 0, mode="L")
    return bw


def is_code_exists(code: str, codes: list[list[str]]) -> bool:
    for code_group in codes:
        if code in code_group:
            return True
    return False


def extract_values_from_text(ocr_text: str, codes: list[list[str]]) -> Report106Codes:
    code_values = {}

    for line in ocr_text.splitlines():
        # Extract all numbers (left to right)
        numbers = re.findall(r'([\d,]+\.\d{2}|[\d,]+)', line)
        numbers = [str(n.replace(',', '')) for n in numbers if n != ',']

        if not numbers:
            continue

        i = len(numbers) - 1  # reading RTL
        while i > 0:
            if {numbers[i], numbers[i - 1]} == {TAX_CODES.CODE_059, TAX_CODES.CODE_068}:
                code_values[TAX_CODES.CODE_068] = numbers[i - 2]
                code_values[TAX_CODES.CODE_069] = numbers[i - 2]
                i -= 3
                continue
            if {numbers[i], numbers[i - 1]} == {TAX_CODES.CODE_089, TAX_CODES.CODE_030}:
                code_values[TAX_CODES.CODE_089] = numbers[i - 2]
                code_values[TAX_CODES.CODE_030] = numbers[i - 2]
                i -= 3
                continue
            if {numbers[i], numbers[i - 1]} == {TAX_CODES.CODE_109, TAX_CODES.CODE_309}:
                try:
                    assert i - 3 >= 0
                    code_values[TAX_CODES.CODE_109] = numbers[i - 3]
                    code_values[TAX_CODES.CODE_309] = numbers[i - 3]
                except:
                    code_values[TAX_CODES.CODE_109] = 0
                    code_values[TAX_CODES.CODE_309] = 0
                i -= 3
                continue
            if numbers[i] == TAX_CODES.CODE_38:
                code_values[TAX_CODES.CODE_36] = numbers[i - 1]
                i -= 2
                continue
            if numbers[i] == TAX_CODES.CODE_082:
                code_values[TAX_CODES.CODE_042] = numbers[i - 1]
                i -= 2
                continue
            if [numbers[i]] in codes:
                j = i - 1
                while j >= 0:
                    if int(numbers[j]) < 1000:
                        j -= 1
                    else:
                        break
                code_values[numbers[i]] = numbers[j]
                i -= 2
            elif any([{numbers[i], numbers[i - 1]} == set(pair) for pair in codes]):
                j = i - 2
                while j >= 0:
                    if int(numbers[j]) < 1000:
                        j -= 1
                    else:
                        break
                code_values[numbers[i]] = numbers[j]
                code_values[numbers[i - 1]] = numbers[j]
                i -= 3
            else:
                i -= 1

    for code, value in code_values.items():
        if code == value:
            code_values[code] = "-1"
        else:
            try:
                code_values[code] = str(int(value))
            except ValueError:
                code_values[code] = value.replace(',', '')

    new_codes = {}
    # deletes keys with -1 or 0 and values less than 1000
    for code in code_values:
        if (code_values[code] != "-1" and
                code_values[code] != "0" and
                int(code_values[code]) > 999):
            new_codes[code] = code_values[code]

    return Report106Codes(codes=new_codes)

import re
from loguru import logger

from tax_authority_api.const import TAX_CODES
from tax_authority_api.schemes import Report106Codes


def preprocess_image(pil_image):
    logger.debug("Starting image preprocessing for OCR")
    # to grayscale
    gray = pil_image.convert("L")
    # apply fixed threshold -> binary (0 or 255) but keep mode "L"
    bw = gray.point(lambda p: 255 if p > 180 else 0, mode="L")
    logger.debug("Image converted to grayscale and binary threshold applied")
    return bw


